-- 1 / 部活動の時間を増やすべきか
INSERT INTO public."ENG_英作文情報" ("英作文ID", "利用者アカウントID", "英検級", "題", "題_中国語", "設問文", "作文本文", "語数", "状態コード", "登録者アカウントID", "更新者アカウントID", "登録元コード", "登録日時", "更新日時") VALUES (900007, 1, 'GRADE1', '部活動の時間を増やすべきか', '是否应该增加社团活动时间', 'Some people say that schools should give students more time for club activities. Do you agree with this opinion? Support your answer with two reasons.', 'I think that students should learn English in elementary school. Because English is very useful for our future. I have a lot of friends in other countries. However, videos are also helpful for listening practice. Therefore we should use both. I think the best way depends on the purpose.', 49, 'A', 1, 1, 'SAMPLE', '2026-09-24T18:05:00.000Z', '2026-09-26T20:30:00.000Z') ON CONFLICT ("英作文ID") DO NOTHING;
