-- 2 / 小学生からの英語教育
INSERT INTO public."ENG_英作文情報" ("英作文ID", "利用者アカウントID", "英検級", "題", "題_中国語", "設問文", "作文本文", "語数", "状態コード", "登録者アカウントID", "更新者アカウントID", "登録元コード", "登録日時", "更新日時") VALUES (900009, 2, 'GRADE2', '小学生からの英語教育', '小学英语教育', 'Some people say that students should learn English in elementary school. Do you agree with this opinion? Give two reasons to support your answer.', 'I think that students should learn English in elementary school. Because English is very useful for our future. I have a lot of friends in other countries. Therefore we can communicate with them in English. And we can learn other cultures through English. I think it is important to start early.', 51, 'A', 2, 2, 'SAMPLE', '2026-09-20T09:12:00.000Z', '2026-09-20T09:20:00.000Z') ON CONFLICT ("英作文ID") DO NOTHING;
INSERT INTO public."ENG_AI添削履歴情報" ("添削ID", "英作文ID", "回数", "状態コード", "英検級", "題_日本語", "題_中国語", "設問文", "作文本文", "語数", "総合得点", "満点", "添削結果JSON", "開始日時", "終了日時", "登録者アカウントID", "登録日時") VALUES (910013, 900009, 1, 'SUCCEEDED', 'GRADE2', '小学生からの英語教育', '小学英语教育', 'Some people say that students should learn English in elementary school. Do you agree with this opinion? Give two reasons to support your answer.', 'I think that students should learn English in elementary school. Because English is very useful for our future. I have a lot of friends in other countries. Therefore we can communicate with them in English. And we can learn other cultures through English. I think it is important to start early.', 51, 6, 16, '{"id":"grading-1-w7fnvz","status":"AI_GRADED","version":"eiken-ai-v1","level":"GRADE2","titleJa":"小学生からの英語教育","titleZh":"小学英语教育","wordCount":51,"score":6,"maxScore":16,"rubricMax":4,"modelAnswer":"I believe that students should learn English in elementary school. Because English is extremely useful for our future. I have numerous friends in other countries. Therefore we can communicate with them in English. And we can learn other cultures through English. I think it is important to start early.","wordRequirement":"80〜100語","taskRequirements":["設問の問いに答える","理由を 2 つ以上挙げる","結論を述べる"],"warnings":["語数が目安（80〜100語）より少なめです。"],"createdAt":"2026-09-20T09:20:00.000Z","japanese":{"title":"主張は伝わります。理由をもう一歩","summary":"まずは主張と理由の対応を整えましょう。内容・構成・語彙・文法の 4 観点で 6 / 16 点です。（語数が目安（80〜100語）より少なめです。）","tags":["設問適合","理由の提示","つながり"],"rubric":[{"key":"内容","score":2,"maxScore":4,"note":"設問の問いには答えられています。理由をもう 1 つ足すと説得力が増します。"},{"key":"構成","score":1,"maxScore":4,"note":"段落の切れ目が分かりにくい箇所があります。1 段落 1 主張を心がけましょう。"},{"key":"語彙","score":1,"maxScore":4,"note":"平易な語に偏っています。同じ意味の別表現を混ぜましょう。"},{"key":"文法","score":2,"maxScore":4,"note":"コンマの位置に誤りがあります。接続副詞の後を確認しましょう。"}],"corrections":[{"original":"I think","corrected":"I believe","category":"表現","reason":"同じ言い回しの繰り返しを避けると、主張が強く伝わります。"},{"original":"very useful","corrected":"extremely useful","category":"語彙","reason":"very よりも程度の強い語を使うと、語彙の評価が上がります。"},{"original":"a lot of","corrected":"numerous","category":"語彙","reason":"口語的な表現を書き言葉に置き換えると、英検のライティングで有利です。"}],"advice":"結論の前に「なぜなら」を 2 回使うと、理由の数を示しやすくなります。","notice":"本結果は公式採点ではありません。英検の 4 観点を参考にした AI 評価です。"},"chinese":{"title":"主张清楚，理由可再充实","summary":"先把主张与理由的对应关系整理好。按内容・结构・词汇・语法四项共 6 / 16 分。（語数が目安（80〜100語）より少なめです。）","tags":["切题","理由陈述","衔接"],"rubric":[{"key":"内容","score":2,"maxScore":4,"note":"已经回答了题目要求。再补一个理由会更有说服力。"},{"key":"構成","score":1,"maxScore":4,"note":"部分段落界限不清。建议一段一个主张。"},{"key":"語彙","score":1,"maxScore":4,"note":"用词偏简单。可以混入同义的高级表达。"},{"key":"文法","score":2,"maxScore":4,"note":"逗号位置有误。请检查连接副词之后。"}],"corrections":[{"original":"I think","corrected":"I believe","category":"表現","reason":"改为更书面、更明确的表达，可提升该项得分。"},{"original":"very useful","corrected":"extremely useful","category":"語彙","reason":"改为更书面、更明确的表达，可提升该项得分。"},{"original":"a lot of","corrected":"numerous","category":"語彙","reason":"改为更书面、更明确的表达，可提升该项得分。"}],"advice":"结论前用两次「因为」，更容易体现理由的数量。","notice":"本结果并非官方评分，是参考英检四项观点的 AI 评价。"}}'::jsonb, '2026-09-20T09:20:00.000Z', '2026-09-20T09:20:00.000Z', 2, '2026-09-20T09:20:00.000Z') ON CONFLICT ("英作文ID", "回数") DO NOTHING;

-- 2 / 読書と動画の学習効果
